    /**
     * Hangi etiket hangi zincirden - cekim saatinden.
     *
     * BIM 18:36-18:43, Metro 20:24-20:37, Migros 21:10-21:15. Saat araliklari
     * ayrik oldugu icin bu tureme guvenli ve fikstur adiyla dogrulanabilir.
     */
    fun chainOf(tag: String): String = when (tag.substringAfter('_').take(2)) {
        "18" -> "BIM"
        "20" -> "Metro"
        "21" -> "Migros"
        else -> "?"
    }

    /** Tek bir zincirin etiketleri. */
    fun of(chain: String): Map<String, TagOcr> = all.filterKeys { chainOf(it) == chain }
}
